INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('study-aspiration-care-home',NULL,'aspiration','Find somewhere they can feel at home and get the care they need.','Find somewhere they can feel at home and get the care they need.','{"geography":"Germany unless the linked source states otherwise","limitations":"Editorial expression of a valued outcome, not a participant quotation or a universal preference.","navigation":{"role":"need","view_id":"study-need-care-home","title":"My parent can no longer live alone","summary":"Find somewhere they can feel at home and get the care they need.","image":"assets/illustrations/study/need-care-home-v5.png","order":0,"lenses":["family"],"affected_lenses":["family","adult","provider"]}}'::jsonb,'candidate','{"basis":"not_assessed","rationale":"Editorial need or fit for discovery; requires direct research and is not an outcome or prevalence claim."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{"kind":"aspiration","title":"Find somewhere they can feel at home and get the care they need.","statement":"Find somewhere they can feel at home and get the care they need.","epistemic_status":"candidate","scope":{"geography":"Germany unless the linked source states otherwise","limitations":"Editorial expression of a valued outcome, not a participant quotation or a universal preference."},"confidence":{"basis":"single_source","rationale":"Editorial expression of a valued outcome, not a participant quotation or a universal preference."},"sources":[{"title":"Finding a suitable care home","url":"https://www.verbraucherzentrale.de/wissen/gesundheit-pflege/pflege-im-heim/so-finden-sie-das-passende-pflegeheim-12023","publisher":"Verbraucherzentrale","published_date":"2025-11-03","stance":"context","limitations":"Consumer guidance, not a prevalence study or a family interv