INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('study-problem-care-fit',NULL,'problem','Finding care that fits the person','Families need to compare care, location, daily life and cost when seeking a suitable home. The consumer guide describes this task; specific failures need firsthand research.','{"geography":"Germany; individual source scope applies","limitations":"Editorial situation; direct first-person research is still needed.","navigation":{"role":"situation","title":"I need to find a home that fits my parent’s care and everyday life","summary":"Family comparing care settings, location, cost and the parent''s preferences.","image":"assets/illustrations/study/study-problem-care-fit-v1.png","order":0,"remaining_question":"existing editorial candidate; provider descriptions are not validation of frequency or severity"}}'::jsonb,'candidate','{"basis":"not_assessed","rationale":"Editorial need or fit for discovery; requires direct research and is not an outcome or prevalence claim."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{"kind":"problem","title":"Finding care that fits the person","statement":"Families need to compare care, location, daily life and cost when seeking a suitable home. The consumer guide describes this task; specific failures need firsthand research.","epistemic_status":"candidate","scope":{"geography":"Germany unless the linked source states otherwise","limitations":"Local editorial synthesis; scope follows the attached sources. No prevalence or effectiveness is inferred."},"confidence":{"basis":"single_source","rationale":"Local editorial synthesis; scope follows the attached sources. No prevalence or effectiveness is inferred."},"sources":[{"title":"Finding a suitable care home","url":"https://www.verbraucherzentrale.de/wissen/gesundheit-pflege/pflege-im-heim/so-finden-sie-das-passende-pflegeheim-12023","publisher":"Verbraucherzentrale","published_date":"2025-11-03","stance":"context","limitations":"Consumer guidance, not a prevalence study or a family interview."}]}}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('study-problem-care-choice',NULL,'problem','Agreeing on a move when wishes differ','A family’s concern about support and a parent’s wish to remain home may pull in different directions. Investigate each person’s wishes rather than assuming disagreement.','{"geography":"Germany; individual source scope applies","limitations":"Editorial situation; direct first-person research is still needed.","navigation":{"role":"situation","title":"My parent and I do not agree about moving into care","summary":"Different preferences need to be heard separately before choosing the next step.","image":"assets/illustrations/study/study-problem-care-choice-v1.png","order":1,"remaining_question":"existing editorial candidate; counselling fit is partial, not proof that disagreement will resolve"}}'::jsonb,'candidate','{"basis":"not_assessed","rationale":"Editorial need or fit for discovery; requires direct research and is not an outcome or prevalence claim."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{"kind":"problem","title":"Agreeing on a move when wishes differ","statement":"A family’s concern about support and a parent’s wish to remain home may pull in different directions. Investigate each person’s wishes rather than assuming disagreement.","epistemic_status":"hypothesis","scope":{"geography":"Germany unless the linked source states otherwise","limitations":"Local editorial synthesis; scope follows the attached sources. No prevalence or effectiveness is inferred."},"confidence":{"basis":"not_assessed","rationale":"Local editorial synthesis; scope follows the attached sources. No prevalence or effectiveness is inferred."},"sources":[{"title":"Finding a suitable care home","url":"https://www.verbraucherzentrale.de/wissen/gesundheit-pflege/pflege-im-heim/so-finden-sie-das-passende-pflegeheim-12023","publisher":"Verbraucherzentrale","published_date":"2025-11-03","stance":"context","limitations":"Consumer guidance, not a prevalence study or a family interview."},{"title":"Housing accessibility among people aged 65+","url":"https://www.dza.de/themen/wohnen-nachbarschaft/detailansicht/wie-altersgerecht-ist-das-wohnen-fuer-menschen-ab-65","publisher":"DZA","published_date":"2026-09-30","stance":"context","limitations":"Population context does not establish an individual wish to stay or the support a particular household needs."}]}}'::jsonb) ON CONFLICT (id) DO NOTHING;
