INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('study-problem-housing-cost',NULL,'problem','Housing costs outlasting income','DZA reports that the share of income spent on housing rose around retirement, especially for tenant households.','{"geography":"Germany; individual source scope applies","limitations":"Editorial situation; direct first-person research is still needed.","navigation":{"role":"situation","title":"After paying rent, I do not have enough for everyday essentials","summary":"Retired tenant with a recurring household budget shortfall.","image":"assets/illustrations/study/study-problem-housing-cost-v1.png","order":0,"remaining_question":"existing editorial candidate; public benefits establish available responses, not adequacy for every household"}}'::jsonb,'candidate','{"basis":"not_assessed","rationale":"Editorial need or fit for discovery; requires direct research and is not an outcome or prevalence claim."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{"kind":"problem","title":"Housing costs outlasting income","statement":"DZA reports that the share of income spent on housing rose around retirement, especially for tenant households.","epistemic_status":"interpretation","scope":{"geography":"Germany unless the linked source states otherwise","limitations":"Historical SOEP analysis, retirement transitions 1993–2019; not current arrears or individual inability to pay."},"confidence":{"basis":"single_source","rationale":"Historical SOEP analysis, retirement transitions 1993–2019; not current arrears or individual inability to pay."},"sources":[{"title":"Retirement and housing costs","url":"https://www.dza.de/themen/wohnen-nachbarschaft/detailansicht/der-uebergang-in-den-ruhestand-verstaerkt-die-belastung-durch-wohnkosten-miethaushalte-sind-besonders-davon-betroffen","publisher":"DZA","published_date":"2023-05-23","stance":"context","limitations":"SOEP analysis of households whose main earner retired aged 55–75 during 1993–2019. Not a current rent-arrears estimate."},{"title":"Wohngeld-Plus","url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/buergerkom/wohngeld-plus/wohngeld-FAQ-artikel.html","publisher":"BMWSB","published_date":null,"stance":"context","limitations":"Indexed official page checked; full page returned 403. Eligibility and actual outcomes are not assessed here."}]}}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('study-problem-housing-support',NULL,'problem','Can housing support close the gap?','Investigate whether housing-cost support is accessible and sufficient for a particular low-income tenant.','{"geography":"Germany; individual source scope applies","limitations":"Editorial situation; direct first-person research is still needed.","navigation":{"role":"situation","title":"I do not know which financial help I can claim","summary":"An older tenant needs help checking eligibility and completing the right applications.","image":"assets/illustrations/study/study-problem-housing-support-v1.png","order":1,"remaining_question":"editorial clarification of existing candidate; direct tenant accounts still needed"}}'::jsonb,'candidate','{"basis":"not_assessed","rationale":"Editorial need or fit for discovery; requires direct research and is not an outcome or prevalence claim."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{"kind":"problem","title":"Can housing support close the gap?","statement":"Investigate whether housing-cost support is accessible and sufficient for a particular low-income tenant.","epistemic_status":"hypothesis","scope":{"geography":"Germany unless the linked source states otherwise","limitations":"An official benefit description establishes an existing response, not unmet eligibility or access barriers."},"confidence":{"basis":"single_source","rationale":"An official benefit description establishes an existing response, not unmet eligibility or access barriers."},"sources":[{"title":"Retirement and housing costs","url":"https://www.dza.de/themen/wohnen-nachbarschaft/detailansicht/der-uebergang-in-den-ruhestand-verstaerkt-die-belastung-durch-wohnkosten-miethaushalte-sind-besonders-davon-betroffen","publisher":"DZA","published_date":"2023-05-23","stance":"context","limitations":"SOEP analysis of households whose main earner retired aged 55–75 during 1993–2019. Not a current rent-arrears estimate."},{"title":"Wohngeld-Plus","url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/buergerkom/wohngeld-plus/wohngeld-FAQ-artikel.html","publisher":"BMWSB","published_date":null,"stance":"context","limitations":"Indexed official page checked; full page returned 403. Eligibility and actual outcomes are not assessed here."}]}}'::jsonb) ON CONFLICT (id) DO NOTHING;
