INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('study-aspiration-wc-object-a11e36230c1d42a53fbca57d',NULL,'aspiration','Step away knowing the person you care for is in good hands.','Step away knowing the person you care for is in good hands.','{"geography":"Germany unless the linked source states otherwise","limitations":"Editorial expression of a valued outcome, not a participant quotation or a universal preference.","navigation":{"role":"need","view_id":"wc-object-a11e36230c1d42a53fbca57d","title":"I need a break from caring","summary":"Take time for myself while my relative receives support they are comfortable with.","image":"assets/illustrations/study/need-care-break-v4.png","order":4,"lenses":["family"],"affected_lenses":["family","adult","provider"]}}'::jsonb,'candidate','{"basis":"not_assessed","rationale":"Editorial need or fit for discovery; requires direct research and is not an outcome or prevalence claim."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{"kind":"aspiration","title":"Step away knowing the person you care for is in good hands.","statement":"Step away knowing the person you care for is in good hands.","epistemic_status":"candidate","scope":{"geography":"Germany unless the linked source states otherwise","limitations":"Editorial expression of a valued outcome, not a participant quotation or a universal preference."},"confidence":{"basis":"single_source","rationale":"Editorial expression of a valued outcome, not a participant quotation or a universal preference."},"sources":[{"title":"Umfrage zur Situation pflegender An- und Zugehöriger","url":"https://www.diakonie.de/informieren/infothek/2025/oktober/umfrage-pflegende-angehoerige","publisher":"Diakonie Deutschland","published_date":null,"stance":"supports","limitations":"Counselor assessments, not direct caregiver