INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('review-problem-break-hours',NULL,'problem','I need a few predictable hours to myself','Family caregiver seeking a recurring daytime break.','{"geography":"Germany; individual source scope applies","limitations":"Editorial need statement, not a quotation. Evidence supports broader context, not this exact segment.","navigation":{"role":"situation","title":"I need a few predictable hours to myself","summary":"Family caregiver seeking a recurring daytime break.","image":"assets/illustrations/study/break-hours-wide-v1.png","order":0,"remaining_question":"Who still cannot take a useful break despite these options, and which requirement prevents it?"}}'::jsonb,'candidate','{"basis":"not_assessed","rationale":"Editorial need or fit for discovery; requires direct research and is not an outcome or prevalence claim."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{"kind":"problem","title":"I need a few predictable hours to myself","statement":"Family caregiver seeking a recurring daytime break.","epistemic_status":"candidate","evidence_ids":["timing","case-daycare"],"sources":[{"title":"Diakonie: survey of care counselling professionals and services","url":"https://www.diakonie.de/informieren/infothek/2025/oktober/umfrage-pflegende-angehoerige","publisher":"Diakonie Deutschland","published_date":"2025-10","evidence_type":"professional_survey","scope":"Germany; August–September 2025; mixed individual and team responses. Methods state 565 respondents, introduction 560.","limitations":"Indirect accounts about caregivers; not caregiver prevalence. Conflicting financial-barrier percentages are not used.","accessed_on":"2026-10-09"},{"title":"Interview with Waltraud Dambrowski: supported Alzheimer Society holiday","url":"https://www.gesund-aktiv-aelter-werde