INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('study-problem-conversation-time',NULL,'problem','Making time for conversation','One resident described difficulty talking with care staff because they lacked time. Her explanation of time allocation is not an independently verified rule.','{"geography":"Germany; individual source scope applies","limitations":"Editorial situation; direct first-person research is still needed.","navigation":{"role":"situation","title":"Making time for conversation","summary":"A resident wants to talk; staff may have other demands on their time.","image":"assets/illustrations/study/study-problem-conversation-time-v1.png","order":3,"remaining_question":"What makes conversation possible on some days and difficult on others?"}}'::jsonb,'candidate','{"basis":"not_assessed","rationale":"Editorial need or fit for discovery; requires direct research and is not an outcome or prevalence claim."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{"kind":"problem","title":"Making time for conversation","statement":"One resident described difficulty talking with care staff because they lacked time. Her explanation of time allocation is not an independently verified rule.","epistemic_status":"candidate","scope":{"geography":"Germany unless the linked source states otherwise","limitations":"One historical resident interview in SeLeP case study 01; no prevalence or cross-case causal claim."},"confidence":{"basis":"single_source","rationale":"One historical resident interview in SeLeP case study 01; no prevalence or cross-case causal claim."},"sources":[{"title":"SeLeP: Selbstbestimmtes Leben im Pflegeheim – Ergebnisbericht (project 2019–2021)","url":"https://pflegenetzwerk-deutschland.de/fileadmin/files/Downloads/pflegenetzwerk-deutschland-selep-ergebnisbericht.pdf","publisher":"Pflegenetzwerk Deutschland (SeLeP project report, University of Augsburg consortium)","published_date":null,"stance":"supports","limitations":"Case studies in selected facilities only; no prevalence claims; resident quotes attributable to specific cases; report date and sampling details not established from read passages"}]}}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('study-problem-care-routines',NULL,'problem','When care routines and personal rhythms differ','A candidate problem: when do organised care routines leave too little room for individual preferences? Separate resident and staff accounts suggest questions, not prevalence.','{"setting":"residential long-term care","geography":"Germany; individual source scope applies","time":"Historical SeLeP project, 2019–2021","limitations":"Editorial situation; direct first-person research is still needed.","navigation":{"role":"situation","title":"Fitting routines to each person","summary":"The same schedule can suit two residents differently.","image":"assets/illustrations/study/study-problem-care-routines-v1.png","order":4,"remaining_question":"What changes when each person’s preference is heard separately?"}}'::jsonb,'candidate','{"basis":"not_assessed","rationale":"Editorial need or fit for discovery; requires direct research and is not an outcome or prevalence claim."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{"kind":"problem","title":"When care routines and personal rhythms differ","statement":"A candidate problem: when do organised care routines leave too little room for individual preferences? Separate resident and staff accounts suggest questions, not prevalence.","epistemic_status":"hypothesis","scope":{"setting":"residential long-term care","geography":"German research context; local facility not established","time":"Historical SeLeP project, 2019–2021","limitations":"Local editorial candidate connecting separate attributed accounts; no common mechanism, current prevalence or purchasing process established."},"confidence":{"basis":"editorial_synthesis","rationale":"A research hypothesis derived from separate historical accounts, not a newly verified finding."},"sources":[{"title":"SeLeP: Selbstbestimmtes Leben im Pflegeheim – Ergebnisbericht (project 2019–2021)","url":"https://pflegenetzwerk-deutschland.de/fileadmin/files/Downloads/pflegenetzwerk-deutschland-selep-ergebnisbericht.pdf","publisher":"Pflegenetzwerk Deutschland (SeLeP project report, University of Augsburg consortium)","published_date":null,"stance":"context","limitations":"Case studies in selected facilities only; no prevalence claims; resident quotes attributable to specific cases; report date and sampling details not established from read passages"}]}}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('study-response-company-careship','company-careship','solution','Careship hourly support','Hourly household help, shopping, companionship and accompaniment.','{"geography":"Selected German regions; postcode and staffing check required.","provider":"Care Companion GmbH / Careship Ambulant GmbH","website":"https://www.careship.de/groundpage","cost":{"status":"published_regional_rates","summary":"Independent helpers: €33/hour, €38 in Bavaria/Baden-Württemberg; Ambulant rates vary (€35.50–45 in listed regions).","currency":"EUR"},"eligibility":{"status":"published","summary":"Self-pay available without Pflegegrad; minimum independent booking 1 hour, regular Ambulant booking 1.5 hours."},"limitations":["Prices dated 28 September 2026; reimbursement requires separate entitlement decision.","No independent outcomes or guaranteed recurring capacity checked."],"navigation":{"role":"solution","title":"Careship hourly support","summary":"Hourly household help, shopping, companionship and accompaniment."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"Existing solutions: staying home, companionship and care breaks","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('review-response-johanniter-day',NULL,'solution','Johanniter day care','Daytime care, group activities and typically morning pickup with afternoon return.','{"geography":"German network; individual centre capacity and transport catchment vary.","limitations":["Website verifies offering, not a vacant place.","Funding amounts intentionally omitted; individual assessment needed."],"provider":"Johanniter","website":"https://www.johanniter.de/dienste-leistungen/pflege-und-begleitung/tagespflege/","cost":{"status":"local_quote_required","summary":"Daily rates include care, accommodation/food, transport and investment charges; personal contribution remains."},"eligibility":{"status":"individual_assessment","summary":"For people needing daytime care; page describes insurance eligibility for care grades 2–5."},"navigation":{"role":"solution","title":"Johanniter day care","summary":"Daytime care, group activities and typically morning pickup with afternoon return."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{"kind":"institutional_response","title":"Johanniter day care","statement":"Daytime care and group activities; transport described.","epistemic_status":"documented","evidence_ids":["day-offer"],"sources":[{"title":"Johanniter Tagespflege","url":"https://www.johanniter.de/dienste-leistungen/pflege-und-begleitung/tagespflege/","publisher":"Johanniter","evidence_type":"provider_description","accessed_on":"2026-10-09","limitations":"Daytime care, activities and transport; locality-specific. Funding figures on the page were not used."}],"scope":{"geography":"Germany; local examples subject to availability","limitations":"Editorial review mapping. Provider offerings are not evidence of unmet demand or effectiveness."}},"research_batch":"Existing solutions: staying home, companionship and care breaks","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-malteser-hausnotruf',NULL,'solution','Malteser home alarm','Home call button connects to a 24-hour response centre; higher packages add local response and inactivity sensing.','{"geography":"Germany; package availability checked by locality.","provider":"Malteser","website":"https://www.malteser.de/hausnotruf/kosten.html","cost":{"status":"published","summary":"Monthly packages €27, €60.40 or €64.90; posted setup promotion €0, subject to current terms.","currency":"EUR"},"eligibility":{"status":"assessment_required","summary":"Home installation and local availability check; insurance pays only where individual necessity is accepted."},"limitations":["No claim of preventing falls or guaranteeing response time.","Promotions and locality must be reconfirmed before purchase."],"navigation":{"role":"solution","title":"Malteser home alarm","summary":"Home call button connects to a 24-hour response centre; higher packages add local response and inactivity sensing."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"Existing solutions: staying home, companionship and care breaks","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-drk-stuttgart-wohnberatung',NULL,'solution','DRK Stuttgart home adaptation advice','Home assessment with written recommendations on aids and building adaptations.','{"geography":"Stuttgart city; referrals elsewhere.","provider":"DRK Kreisverband Stuttgart","website":"https://www.drk-stuttgart.de/wohnberatung.html","cost":{"status":"published","summary":"Home visit including report €150; €75 with city Bonuskarte. General advice in model home free.","currency":"EUR"},"eligibility":{"status":"published","summary":"All Stuttgart residents; tenants, owners and landlords included."},"limitations":["Specific local offering; do not copy this price to nationwide DRK advice.","Actual building feasibility and funding unknown until assessment."],"navigation":{"role":"solution","title":"DRK Stuttgart home adaptation advice","summary":"Home assessment with written recommendations on aids and building adaptations."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"Existing solutions: staying home, companionship and care breaks","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-rewe-lieferservice',NULL,'solution','REWE grocery delivery','Online-selected groceries delivered to the apartment door.','{"geography":"Germany; delivery postcode and slot dependent.","provider":"REWE Markt GmbH or selected REWE merchant","website":"https://www.rewe.de/service/agb/lieferservice","cost":{"status":"published_conditional","summary":"Goods plus €0–4.90 delivery; minimum basket varies by postcode; drink-crate surcharges may apply. Merchant terms may differ.","currency":"EUR"},"eligibility":{"status":"published","summary":"Adult customer; online registration, supported address and delivery slot required."},"limitations":["Displayed terms dated 13 October 2023, still served on access date.","No test order or postcode booking performed."],"navigation":{"role":"solution","title":"REWE grocery delivery","summary":"Online-selected groceries delivered to the apartment door."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"Existing solutions: staying home, companionship and care breaks","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-lifta-treppenlift','company-lifta','solution','Lifta stairlifts','Installed seated lifts for indoor/outdoor stairs, including straight and curved configurations.','{"geography":"Germany; individual staircase survey.","provider":"Lifta","website":"https://www.lifta.de/treppenlift","cost":{"status":"published_indicative","summary":"One-floor indoor straight €5,500–9,900; curved €10,000–17,000. Final quote depends on layout and options.","currency":"EUR"},"eligibility":{"status":"assessment_required","summary":"Building and user suitability require survey; age alone is not an eligibility condition."},"limitations":["Provider ranges, not binding quotations or independent effectiveness evidence.","Subsidy claims not repeated without payer confirmation."],"navigation":{"role":"solution","title":"Lifta stairlifts","summary":"Installed seated lifts for indoor/outdoor stairs, including straight and curved configurations."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"Existing solutions: staying home, companionship and care breaks","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('review-response-silbernetz',NULL,'solution','Silbernetz telephone companionship','Free anonymous conversation line plus optional weekly matched telephone friendship.','{"geography":"Germany.","limitations":["60+ is actual service scope, independent of illustration convention.","Matching delay and effects on loneliness not established here."],"provider":"Silbernetz e.V.","website":"https://silbernetz.org/","cost":{"status":"published","summary":"Free via 0800 4 70 80 90."},"eligibility":{"status":"published","summary":"People aged 60+; friendship requests must come from the older person, not third parties."},"navigation":{"role":"solution","title":"Silbernetz telephone companionship","summary":"Free anonymous conversation line plus optional weekly matched telephone friendship."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{"kind":"institutional_response","title":"Silbernetz","statement":"Hotline and regular telephone friendship.","epistemic_status":"documented","evidence_ids":["phone-offer","phone-evaluation"],"sources":[{"title":"Silbernetz: Über uns","url":"https://silbernetz.org/ueber-uns/","publisher":"Silbernetz","evidence_type":"provider_description","accessed_on":"2026-10-09","limitations":"Telephone contact for people 60+; hotline and regular telephone friendship are different formats."},{"title":"ReWiSil evaluation","url":"https://www.dza.de/forschung/aktuelle-projekte/evaluationsprojekt-reichweite-und-wirkung-der-silbernetz-hotline-rewisil","publisher":"DZA","evidence_type":"research_project","accessed_on":"2026-10-09","limitations":"Evaluation results available June 2026; project page inspected, full results and methods not appraised here. Hotline only, not all Silbernetz services."}],"scope":{"geography":"Germany; local examples subject to availability","limitations":"Editorial review mapping. Provider offerings are not evidence of unmet demand or effectiveness."}},"research_batch":"Existing solutions: staying home, companionship and care breaks","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-retla-telefon-engel',NULL,'solution','Retla Telefon-Engel','Matches older people with volunteers for recurring telephone conversations.','{"geography":"Germany.","provider":"Retla e.V.","website":"https://retla.org/telefon-engel/","cost":{"status":"published","summary":"No service charge; ordinary telephone charges only."},"eligibility":{"status":"published_partial","summary":"Older people wanting conversation; register by phone Monday–Friday 09:00–12:00."},"limitations":["Provider evaluation claims were not independently assessed and are excluded.","Waiting times and language matching unknown."],"navigation":{"role":"solution","title":"Retla Telefon-Engel","summary":"Matches older people with volunteers for recurring telephone conversations."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"Existing solutions: staying home, companionship and care breaks","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-radeln-ohne-alter',NULL,'solution','Radeln ohne Alter outings','Volunteer pilots take people on shared rickshaw outings.','{"geography":"German local groups; not universal coverage.","provider":"Radeln ohne Alter Deutschland e.V. and local groups","website":"https://radelnohnealter.de/passagier/","cost":{"status":"published","summary":"Rides free."},"eligibility":{"status":"published","summary":"People unable to pedal themselves; local rickshaw, insured operation and volunteer availability required."},"limitations":["No claim that every wheelchair user can board every rickshaw.","Weather, booking capacity and specific accessibility unknown."],"navigation":{"role":"solution","title":"Radeln ohne Alter outings","summary":"Volunteer pilots take people on shared rickshaw outings."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"Existing solutions: staying home, companionship and care breaks","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-malteser-besuchsdienst',NULL,'solution','Malteser visits and accompaniment','Volunteers visit at home for conversation and activities, with optional walks or telephone visits.','{"geography":"Germany; find a local service by postcode.","provider":"Malteser","website":"https://www.malteser.de/besuchsdienst.html","cost":{"status":"published","summary":"Visits free."},"eligibility":{"status":"published_partial","summary":"People seeking company and exchange; local matching needed."},"limitations":["Explicitly not a replacement nursing/housekeeping service.","Do not map it as guaranteed caregiver respite."],"navigation":{"role":"solution","title":"Malteser visits and accompaniment","summary":"Volunteers visit at home for conversation and activities, with optional walks or telephone visits."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"Existing solutions: staying home, companionship and care breaks","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-johanniter-short-stay',NULL,'solution','Johanniter short-term residential care','Temporary care in a residential facility while family carers are away.','{"geography":"Germany; referenced listing is Berlin central contact, not proof of a particular vacant bed.","provider":"Johanniter Seniorenhäuser GmbH","website":"https://www.johanniter.de/dienste-leistungen/angebote-fuer-privatpersonen/lokale-angebote/dienstleistung/kurzzeitpflege-3599/","cost":{"status":"unknown","summary":"No rate on opened page; facility quote required."},"eligibility":{"status":"assessment_required","summary":"People needing temporary care; admission suitability and available places must be confirmed."},"limitations":["Provider-level offering verified; dates, price and facility selection unresolved.","Do not inherit historical generic short-stay evidence as this provider’s outcomes."],"navigation":{"role":"solution","title":"Johanniter short-term residential care","summary":"Temporary care in a residential facility while family carers are away."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"Existing solutions: staying home, companionship and care breaks","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-alzheimer-hamburg-rerik',NULL,'solution','Supported breaks in Rerik','Joint holiday with scheduled group support for the person with early dementia.','{"geography":"Rerik, Mecklenburg-Vorpommern; organised from Hamburg.","provider":"Alzheimer Gesellschaft Hamburg with AWOSANO gGmbH","website":"https://www.alzheimer-hamburg.de/freizeitkultur/betreute-urlaube","cost":{"status":"unknown","summary":"No current package price on opened page."},"eligibility":{"status":"published","summary":"Pairs only; early dementia, largely independent with small assistance needs; 8–10 pairs."},"limitations":["4–13 October 2026 trip already underway on research date.","18–27 May and 27 September–6 October 2027 are planned, not confirmed bookable capacity.","Do not generalise to advanced dementia or independent solo travel."],"navigation":{"role":"solution","title":"Supported breaks in Rerik","summary":"Joint holiday with scheduled group support for the person with early dementia."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"Existing solutions: staying home, companionship and care breaks","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-aai-supported-holidays',NULL,'solution','Alzheimer Angehörigen-Initiative supported holidays','Joint trips with activities, group supervision and support with care.','{"geography":"Destinations include Burg/Spreewald; Berlin-based organiser.","provider":"Alzheimer Angehörigen-Initiative","website":"https://alzheimer-organisation.de/demenz-urlaub/","cost":{"status":"quote_required","summary":"Request current quotation; historical price/reimbursement text excluded."},"eligibility":{"status":"assessment_required","summary":"People with dementia travelling with relatives; provider asks about mobility."},"limitations":["Main offering and inquiry form verified.","Burg detail page has stale reimbursement amount and 2020 date despite later metadata; do not reuse financial guidance.","2026 directory used only for discovery; past April departure is not future availability."],"navigation":{"role":"solution","title":"Alzheimer Angehörigen-Initiative supported holidays","summary":"Joint trips with activities, group supervision and support with care."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"Existing solutions: staying home, companionship and care breaks","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-malteser-mobile-einkaufshilfe',NULL,'solution','Malteser Mobile Einkaufswagen','Volunteers collect a group for accompanied shopping and conversation.','{"geography":"Germany; participating local services.","provider":"Malteser","website":"https://www.malteser.de/einkaufshilfe.html","cost":{"status":"published","summary":"Service free; personal purchases separate."},"eligibility":{"status":"published_partial","summary":"Older people needing shopping support and wanting social contact; local service check."},"limitations":["Free service does not mean free groceries.","Not asserted available in every postcode."],"navigation":{"role":"solution","title":"Malteser Mobile Einkaufswagen","summary":"Volunteers collect a group for accompanied shopping and conversation."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"Existing solutions: staying home, companionship and care breaks","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-alzheimer-hamburg-home-visits',NULL,'solution','Alzheimer Hamburg home support visits','Trained volunteers spend planned time with a person with dementia at home or nearby.','{"geography":"Hamburg.","provider":"Alzheimer Gesellschaft Hamburg e.V.","website":"https://www.alzheimer-hamburg.de/angebote/betreuung/haeuslicher-besuchsdienst","cost":{"status":"published","summary":"€12–15/hour; provider describes reimbursement from care grade 1, subject to individual entitlement.","currency":"EUR"},"eligibility":{"status":"published","summary":"People with dementia cared for by relatives at home; coordinator assessment and introduction."},"limitations":["No medical/nursing coverage inferred.","Current waitlist and payer approval not checked."],"navigation":{"role":"solution","title":"Alzheimer Hamburg home support visits","summary":"Trained volunteers spend planned time with a person with dementia at home or nearby."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"Existing solutions: staying home, companionship and care breaks","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-drk-leer-transport',NULL,'solution','DRK Leer accessible transport','Wheelchair, carrying-chair and lying transport to medical or private destinations.','{"geography":"Landkreis Leer; longer journeys by agreement.","provider":"DRK Kreisverband Leer","website":"https://www.drk-leer.de/angebote/fahrdienst.html","cost":{"status":"quote_required","summary":"No public fare on opened page; medical reimbursement conditional."},"eligibility":{"status":"published","summary":"People with restricted mobility; transport type agreed individually."},"limitations":["Do not treat locally verified transport as nationwide service coverage.","Provider says accompaniment can travel if declared when booking."],"navigation":{"role":"solution","title":"DRK Leer accessible transport","summary":"Wheelchair, carrying-chair and lying transport to medical or private destinations."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"Existing solutions: staying home, companionship and care breaks","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-drk-leer-hausnotruf',NULL,'solution','DRK Leer home alarm','Wearable button opens voice contact to a staffed centre, which alerts agreed contacts or emergency help.','{"geography":"Landkreis Leer.","provider":"DRK Kreisverband Leer","website":"https://www.drk-leer.de/angebote/alltagshilfen/hausnotruf.html","cost":{"status":"published_with_conflict","summary":"Basic €27/month; additional service package €19/month. Reimbursement section inconsistently says €25.50; confirm before relying on it.","currency":"EUR"},"eligibility":{"status":"assessment_required","summary":"Provider consultation and home range check; insurance eligibility separately assessed."},"limitations":["Conflicting insurance figure retained as uncertainty, not silently corrected.","No response-time or clinical-outcome guarantee inferred."],"navigation":{"role":"solution","title":"DRK Leer home alarm","summary":"Wearable button opens voice contact to a staffed centre, which alerts agreed contacts or emergency help."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"Existing solutions: staying home, companionship and care breaks","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-aok-pflegenavigator',NULL,'solution','AOK-Pflegenavigator','Searches care homes and other care services and presents information about provision and care quality.','{"geography":"Germany; local results depend on search region","provider":"AOK","website":"https://www.aok.de/pk/pflegenavigator/","cost":{"status":"not verified","note":"No consumer price captured; do not label free solely from access to the page."},"eligibility":{"status":"public search page observed","note":"Specific service access and insurance eligibility must be checked separately."},"limitations":["No successful search or booking was tested.","Published listing does not establish a vacancy or suitability for a particular parent."],"navigation":{"role":"solution","title":"AOK-Pflegenavigator","summary":"Searches care homes and other care services and presents information about provision and care quality."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"solutions-care-home-rent-work-2026-10-09","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-compass-pflegeberatung',NULL,'solution','compass Pflegeberatung','Counsellors discuss care needs and options and help organise care arrangements.','{"geography":"Germany; telephone, video and local advisers","provider":"compass private pflegeberatung GmbH","website":"https://www.compass-pflegeberatung.de/beratungsangebote/das-ist-pflegeberatung","cost":{"status":"published","note":"Counselling advertised as free."},"eligibility":{"status":"partly verified","note":"Telephone advice for everyone; individual statutory counselling entitlement described for privately insured people and relatives. Confirm access to home visits."},"limitations":["No resolution of family disagreement or placement outcome established.","Appointment wait and particular-home availability unknown."],"navigation":{"role":"solution","title":"compass Pflegeberatung","summary":"Counsellors discuss care needs and options and help organise care arrangements."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"solutions-care-home-rent-work-2026-10-09","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('wc-object-6e0bbbaef2c130696555fba3',NULL,'institutional_response','Berlin Pflegestützpunkte: public care counseling and access routes','Berlin’s official page describes the Berliner Pflegestützpunkte as jointly run by the care and health insurers with the Land Berlin. It describes free, independent counseling for older people, care recipients and relatives, in person, by phone, at home or by video. The network website lists service telephone 0800 59 500 59 (Monday–Friday, 9–18), recommends appointments for personal visits and links video booking to its locations page.','{"time":"Official pages captured 2026-10-09; publication dates unknown","setting":"Home care counseling","geography":"Berlin; distant relatives can seek advice, home visits locally restricted","limitations":["No care place supplied directly.","Berlin example must not be presented as the same service operating nationally."],"stakeholders":["older people","care recipients","family caregivers"],"provider":"Berlin health/care insurers and Land Berlin","website":"https://www.pflegestuetzpunkteberlin.de/ueber-uns/ueber-uns-meistgestellte-fragen/","cost":{"status":"published","note":"Free advice."},"eligibility":{"status":"published","note":"Statutorily insured people, relatives and interested citizens; confirm local appointment and home-visit arrangements."},"navigation":{"role":"solution","title":"Pflegestützpunkte Berlin","summary":"Individual advice about home care, alternative living settings, financing and transitions."}}'::jsonb,'candidate','{"basis":"single_source","rationale":"Government and official counseling-network descriptions with responsible bodies, Berlin scope and contact routes; access, capacity and outcomes unverified."}'::jsonb,'{"job_id":"5a45c0f8032af6072cd050ac64733d575b96d4694f4f912138b75c8f1936dab9","batch_id":"berlin-counseling-internal-20261009-v1","finding_id":"finding-c2c537b6ac6ff64dcb72c7da","managed_by":"whocares-indexer.atlas-publish.v1","record_sha256":"e23f3a18cc2a5419df9a7a9f14249ebe56755ad1f5ec64d38b88760f8e106101","manifest_sha256":"804c6ae0a4faebf878c967a6f02da8ef7fa9aaf6702206dc7a55012971b59e27","editorial_review":{"actor":"Codex editorial supervision","reason":"Inspected both complete official captures and corrected independent reviews. One Berlin institutional counseling response with explicit responsible bodies, audience and contact routes. Governance and location finder are supporting context, not extra offerings. No access, capacity, national-coverage or outcome claim. Internal database duplicate identity checks returned no matching entries or objects. Preserve prior FLEXXI/legal holds. Reuse existing caregiver relief space with separately sourced editorial context relationship. Internal branch only.","reviewed_at":"2026-10-09T01:51:34.034216+00:00","audit_event_id":1554},"principles_sha256":"1698c1ce402af9694166b15938d24fb9fb05c55e85a330b4e589b7dca5b2a8c2","finding_review_hash":"65c9be0528759baafbaccf66fa7d85a535f0bceeb8e2a7ee95c4b25718111ee5","finding_payload_sha256":"a45d793518566594e4e044d6daf084f0e94cd4ab61bd99fe3be0d03216a1fb4f","original_epistemic_status":"candidate","research_batch":"solutions-care-home-rent-work-2026-10-09","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO UPDATE SET scope=atlas.objects.scope || jsonb_build_object('navigation',EXCLUDED.scope->'navigation') WHERE atlas.objects.scope->'navigation' IS DISTINCT FROM EXCLUDED.scope->'navigation';
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-biva-beratungsdienst',NULL,'solution','BIVA-Beratungsdienst','Advice on civil and social-law questions concerning care-home living and residents'' rights.','{"geography":"Germany","provider":"BIVA-Pflegeschutzbund e.V.","website":"https://www.biva.de/verein/die-biva/","cost":{"status":"not verified","note":"Membership advice; current membership and separate review fees not captured."},"eligibility":{"status":"published","note":"Advice contact is for members."},"limitations":["Not a vacancy finder or direct care provider.","Separate contract-review page failed to load; no specific contract-review price claimed."],"navigation":{"role":"solution","title":"BIVA-Beratungsdienst","summary":"Advice on civil and social-law questions concerning care-home living and residents'' rights."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"solutions-care-home-rent-work-2026-10-09","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-johanniter-stift-berlin-lichterfelde',NULL,'solution','Johanniter-Stift Berlin-Lichterfelde','Residential accommodation, care and social support in a named home.','{"geography":"Finckensteinallee 123/125, 12205 Berlin","provider":"Johanniter-Seniorenhäuser","website":"https://www.johanniter.de/johanniter-seniorenhaeuser/standorte/johanniter-stift-berlin-lichterfelde/","cost":{"status":"not verified","note":"Request a current individual quote; no price captured."},"eligibility":{"status":"partly verified","note":"Provider says all care grades; admission assessment and vacancy unverified."},"limitations":["Capacity is not vacancy.","Quality, affordability, accessibility for a specific person and admission time not independently checked."],"navigation":{"role":"solution","title":"Johanniter-Stift Berlin-Lichterfelde","summary":"Residential accommodation, care and social support in a named home."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"solutions-care-home-rent-work-2026-10-09","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('study-response-wohngeld',NULL,'solution','Wohngeld – Mietzuschuss','Means-tested contribution toward rent for eligible households.','{"geography":"German benefit; this source verifies the Berlin route","limitations":["Not automatically paid or universally eligible.","No claim that award closes an individual''s entire budget gap."],"provider":"Local housing authorities; Berlin application route verified","website":"https://service.berlin.de/dienstleistung/120656/","cost":{"status":"published","note":"Application has no fee; benefit amount individually assessed."},"eligibility":{"status":"published conditions, not individual assessment","note":"Income/rent/household test and exclusions apply; use local authority."},"navigation":{"role":"solution","title":"Wohngeld – Mietzuschuss","summary":"Means-tested contribution toward rent for eligible households."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{"kind":"institutional_response","title":"Wohngeld: help with housing costs","statement":"BMWSB describes Wohngeld as a housing-cost subsidy. Its indexed official description includes people with low pensions among potential recipients. Individual eligibility and outcomes are not established here.","epistemic_status":"documented","scope":{"geography":"Germany","limitations":"Official indexed description checked on 2026-10-09; full page returned 403. No assessment of a particular person’s entitlement."},"confidence":{"rationale":"Official service description; not evidence of outcomes."},"sources":[{"title":"Wohngeld-Plus","url":"https://www.bmwsb.bund.de/SharedDocs/faqs/DE/buergerkom/wohngeld-plus/wohngeld-FAQ-artikel.html","publisher":"BMWSB","published_date":null,"stance":"context","limitations":"Indexed official page checked; full page returned 403. Eligibility and actual outcomes are not assessed here."}]},"research_batch":"solutions-care-home-rent-work-2026-10-09","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-grundsicherung-im-alter',NULL,'solution','Grundsicherung im Alter','Means-tested support for necessary living costs, including eligible housing and heating.','{"geography":"German benefit; Berlin application route verified","provider":"Local social welfare authority; Berlin route verified","website":"https://service.berlin.de/dienstleistung/324394/","cost":{"status":"published","note":"Application free; award individually assessed."},"eligibility":{"status":"published conditions, not individual assessment","note":"Retirement-age and means tests; separate permanent-disability route also exists."},"limitations":["Not interchangeable or automatically additive with Wohngeld.","No individual benefit calculation or decision timeframe verified."],"navigation":{"role":"solution","title":"Grundsicherung im Alter","summary":"Means-tested support for necessary living costs, including eligible housing and heating."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"solutions-care-home-rent-work-2026-10-09","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-caritas-berlin-sozialberatung',NULL,'solution','Caritas Berlin – Allgemeine Soziale Beratung','Counsellors help clarify welfare entitlements, official decisions and financial difficulties, including in old age.','{"geography":"Listed Berlin counselling locations; local contact rules vary","provider":"Caritasverband für das Erzbistum Berlin e.V.","website":"https://www.caritas-berlin.de/beratungundhilfe/berlin/allgemeinesozialeberatung/allgemeine-soziale-beratung","cost":{"status":"published","note":"Free counselling."},"eligibility":{"status":"partly verified","note":"Open described remit; some district services explicitly target district residents."},"limitations":["Counselling is not an award of benefits.","Current appointment waits and individual outcomes unverified."],"navigation":{"role":"solution","title":"Caritas Berlin – Allgemeine Soziale Beratung","summary":"Counsellors help clarify welfare entitlements, official decisions and financial difficulties, including in old age."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"solutions-care-home-rent-work-2026-10-09","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-berlin-mietschuldenhilfe',NULL,'solution','Berlin – help with rent arrears','Case-by-case assumption of eligible rent debts to preserve housing.','{"geography":"Berlin procedure verified","provider":"Responsible Berlin social welfare benefits office","website":"https://www.berlin.de/sen/soziales/soziale-sicherung/kosten-der-unterkunft/kosten-der-unterkunft-fragen-und-antworten/","cost":{"status":"conditional","note":"May be repayable loan; grant possible in specified cases. Individual terms must be confirmed."},"eligibility":{"status":"case-by-case","note":"Appropriate housing, circumstances, existing assistance and other resources are considered."},"limitations":["Exceptional support, not guaranteed debt cancellation.","Do not apply the page''s SGB II details indiscriminately to older SGB XII applicants."],"navigation":{"role":"solution","title":"Berlin – help with rent arrears","summary":"Case-by-case assumption of eligible rent debts to preserve housing."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"solutions-care-home-rent-work-2026-10-09","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-berlin-wbs',NULL,'solution','Berlin Wohnberechtigungsschein (WBS)','Certificate establishing eligibility to apply for income-restricted social housing.','{"geography":"Berlin","provider":"Berlin district housing offices","website":"https://service.berlin.de/dienstleistung/120671/","cost":{"status":"published","note":"Certificate application free; rental costs and moving costs separate."},"eligibility":{"status":"published conditions, not individual assessment","note":"Income and household rules apply; Berlin''s rules are not assumed identical elsewhere."},"limitations":["Does not provide a home or pay current rent arrears.","Accessible vacancies, waiting time and suitability near existing social ties unknown."],"navigation":{"role":"solution","title":"Berlin Wohnberechtigungsschein (WBS)","summary":"Certificate establishing eligibility to apply for income-restricted social housing."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"solutions-care-home-rent-work-2026-10-09","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-voize-altenpflege','company-voize','solution','voize for residential elder care','Speech-based care records with drafts reviewed by staff, plus handover information and team notes.','{"geography":"German-language residential elder-care offering; facility integration required","provider":"voize","website":"https://www.voize.ai/de/loesungen/altenpflege","cost":{"status":"quote required","note":"Per cared-for person licensing; no numeric price captured."},"eligibility":{"status":"facility purchase","note":"Requires compatible documentation integration and local implementation; individual worker cannot assume access."},"limitations":["Vendor time-saving and quality claims were not independently assessed; no saved-care-time claim adopted.","Accuracy, staff verification time, integration cost and resident preferences require local evaluation."],"navigation":{"role":"solution","title":"voize for residential elder care","summary":"Speech-based care records with drafts reviewed by staff, plus handover information and team notes."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"solutions-care-home-rent-work-2026-10-09","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-medifox-md-stationaer','company-medifox','solution','MD Stationär','Care records, mobile/offline documentation, shift information and staffing modules within one residential-care system.','{"geography":"German residential care market","provider":"MEDIFOX DAN","website":"https://www.medifoxdan.de/anwendungsgebiete/stationaere-pflege","cost":{"status":"not verified","note":"Demo/contact route; module, hardware and implementation charges not captured."},"eligibility":{"status":"facility purchase","note":"Residential-care operator adoption and module configuration required."},"limitations":["No assurance of saved time, error-free records or increased personal attention adopted from marketing.","Module compatibility, actual staffing availability and implementation burden unverified."],"navigation":{"role":"solution","title":"MD Stationär","summary":"Care records, mobile/offline documentation, shift information and staffing modules within one residential-care system."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"solutions-care-home-rent-work-2026-10-09","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-vivendi-pep',NULL,'solution','Vivendi PEP','Rota and absence planning, replacement search, and staff self-service for requests and schedules.','{"geography":"German social and healthcare market","provider":"Connext","website":"https://www.vivendi.de/software/vivendi-pep.aspx","cost":{"status":"not verified","note":"Sales contact offered; price and implementation fee not captured."},"eligibility":{"status":"organisation purchase","note":"Requires deployment by employer; local rules and staff data configuration."},"limitations":["Software cannot guarantee that any suitable colleague is available.","No causal effect on resident care time or employee fairness established."],"navigation":{"role":"solution","title":"Vivendi PEP","summary":"Rota and absence planning, replacement search, and staff self-service for requests and schedules."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"solutions-care-home-rent-work-2026-10-09","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('solution-einstep-implementation-support',NULL,'solution','EinSTEP training and implementation support','Training resources and association support for adopting the four-part documentation model with structured information collection and individual measures planning.','{"geography":"Germany; long-term home and residential care, also day and short-term care","provider":"Projektbüro EinSTEP and participating care associations","website":"https://www.ein-step.de/schulungsunterlagen","cost":{"status":"partly known","note":"Public resources accessible; training/support fees and association access not verified."},"eligibility":{"status":"programme scope verified","note":"Care facility implementation; contact relevant association for support terms."},"limitations":["This entry is the named support programme, not a generic ''better documentation'' response class.","No automatic reduction of workload or improved resident experience established for a particular facility."],"navigation":{"role":"solution","title":"EinSTEP training and implementation support","summary":"Training resources and association support for adopting the four-part documentation model with structured information collection and individual measures planning."}}'::jsonb,'documented','{"basis":"single_source","rationale":"Official source describes the offering; effectiveness and current capacity were not independently established."}'::jsonb,'{"method":"needs-situations-solutions-20261009","reviewed_by":"Codex: user-directed hierarchy integration","date":"2026-10-09","original_local_record":{},"research_batch":"solutions-care-home-rent-work-2026-10-09","verified_on":"2026-10-09"}'::jsonb) ON CONFLICT (id) DO NOTHING;
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('wc-object-0fa22338740ba4f0e4c9d81f',NULL,'solution','AVACANO care-place search, with mediatogo GmbH named as contact','AVACANO describes an internet platform displaying available care places and claims that its listings are updated daily. Its home page lists a Kurzzeitpflege category. Its contact page names mediatogo GmbH at Bisinger Berg 1, 72415 Grosselfingen. These are provider descriptions, not independent verification of legal identity, listing freshness, actual capacity or successful placements.','{"time":"Pages captured 2026-10-09; publication dates unknown","setting":"Care-place directory including short-term care category","geography":"German-language care search; contact address in Grosselfingen, Germany; exact service coverage unknown","limitations":"Self-described offering/contact identity only; no register check, current capacity, service uptake, comprehensive coverage or outcome verification.","stakeholders":["care seekers","family caregivers","care providers"],"navigation":{"role":"solution","title":"AVACANO care-place search","summary":"Search for care places. Availability and personal fit require direct confirmation."}}'::jsonb,'candidate','{"basis":"single_source","rationale":"Provider self-description and contact identification, supported by its captured homepage/contact page; availability and outcomes unknown."}'::jsonb,'{"job_id":"5a45c0f8032af6072cd050ac64733d575b96d4694f4f912138b75c8f1936dab9","batch_id":"avacano-offering-internal-20261009-v1","finding_id":"finding-a85cb3b0475a4eb2c2a4c471","managed_by":"whocares-indexer.atlas-publish.v1","record_sha256":"43091d38e9c475e30f08e66b09e52be78ee358abaf0b9186900ae745b1488f5f","manifest_sha256":"ff8b43151bda0fefd5a276ddcb31b825d02e1d5e21c8ab67569e899168113ebe","editorial_review":{"actor":"Codex editorial supervision","reason":"Inspected exact homepage/contact/category captures and independent reviews. Narrowed to one provider-described care-place search identity. Removed uncited hotline and unverified benefit rule. Count labels lack reliable facility pairing and are background only. Operator is self-identified contact, not independently register-verified. No Avacano or mediatogo match in internal entries/objects. One candidate solution and explicit editorial context edge; no new problem space or public company record. Internal branch only.","reviewed_at":"2026-10-09T01:22:04.047861+00:00","audit_event_id":1451},"principles_sha256":"1698c1ce402af9694166b15938d24fb9fb05c55e85a330b4e589b7dca5b2a8c2","finding_review_hash":"358155adf765bf9b776e2ee6736d16bbe7927c4d4237016cb86a7a672e5ef770","finding_payload_sha256":"3a127a49f83faad0798a014f45124333b65e0e943d3090e2a98765fcbd4ad45b","original_epistemic_status":"candidate"}'::jsonb) ON CONFLICT (id) DO UPDATE SET scope=atlas.objects.scope || jsonb_build_object('navigation',EXCLUDED.scope->'navigation') WHERE atlas.objects.scope->'navigation' IS DISTINCT FROM EXCLUDED.scope->'navigation';
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('wc-object-919ce94c44fc5a075587e852',NULL,'institutional_response','Harzklinikum advertises a social service supporting discharge and aftercare','Harzklinikum describes its hospital social service as helping patients prepare for discharge and return home, including help arranging home care, applications for short-term care after a hospital stay, support finding a care facility, and information to relatives, care facilities and GPs as part of discharge planning.','{"time":"undated web page, retrieved 2026-10","method":"official hospital webpage (provider statement)","setting":"hospital discharge management / social service","geography":"Saxony-Anhalt, Germany (Harzklinikum, Landkreis Harz)","limitations":"Official hospital self-description, not proof of successful placements, current staffing, downstream care capacity or outcomes. Page is undated. A recipient-specific contact route and legal operating entity are not established by attached passages.","perspective":"system","navigation":{"role":"solution","title":"Harzklinikum discharge support","summary":"Discharge social service at Harzklinikum. Scope is this hospital; follow-up capacity is not guaranteed."}}'::jsonb,'candidate','{"basis":"single_source","rationale":"Official hospital description of discharge coordination; contact route, legal operating entity, actual access and outcomes unknown."}'::jsonb,'{"job_id":"91947fd9fc799811ce96c498b440b00dba4f3fbcadf112e6429602af81e95e91","batch_id":"hospital-social-service-internal-20261009-v1","finding_id":"finding-7ad6b38e5f55b00125c0107a","managed_by":"whocares-indexer.atlas-publish.v1","record_sha256":"ba320df6b810d4b383bbabb3a35acba977be2858e7b306737c4eedb7480a85e4","manifest_sha256":"82650cb75afb7a45a1d50369b0a1df49a7dbbd8a0b25d652d8379d15fd441582","editorial_review":{"actor":"Codex editorial supervision","reason":"Inspected full captured official hospital text and independently reviewed narrowed findings. Admit one institution-described service with hospital identity, advertised patient support and explicit unknown recipient contact/legal entity. No current capacity or successful-placement claims. Database alias search found no Harzklinikum object/entry. Reuse participation space with separately scoped evidence. Internal branch only.","reviewed_at":"2026-10-09T02:37:08.944091+00:00","audit_event_id":1749},"principles_sha256":"1698c1ce402af9694166b15938d24fb9fb05c55e85a330b4e589b7dca5b2a8c2","finding_review_hash":"7f723da00b24e064b91003265f4309c819651a62ae89031f7808d2d0c871ace7","finding_payload_sha256":"7829cb1fe72496197f5ae6c059874fdcaf2fc0031e568539a610d3503866a90b","original_epistemic_status":"candidate"}'::jsonb) ON CONFLICT (id) DO UPDATE SET scope=atlas.objects.scope || jsonb_build_object('navigation',EXCLUDED.scope->'navigation') WHERE atlas.objects.scope->'navigation' IS DISTINCT FROM EXCLUDED.scope->'navigation';
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('wc-object-2ca5b9a5d800c0ecec85adc1',NULL,'institutional_response','Hamburg Pflegestuetzpunkte: publicly described care counseling and access routes','Hamburg’s official page describes Pflegestuetzpunkte jointly supported by health and care insurers and the City of Hamburg, advising people needing help or care and their relatives. It describes information about care at home, support with insurance and social-benefit applications, financing advice and longer-term coordination of individual steps. The page advertises drop-in counseling on Mondays 8–12 and Thursdays 14–18, telephone counseling on Tuesdays and Fridays 8–12, and personal counseling at home. These are institutional service descriptions, not verified appointments, current capacity or care outcomes.','{"time":"Captured9October2026; publication/update date not established in complete saved text or inspected raw HTML date metadata","method":"Official Hamburg government institutional self-description","setting":"Care counseling for people needing help/care and relatives","geography":"Hamburg, Germany","limitations":"Advertised service and opening times, not checked current capacity, access, uptake or effectiveness. No nationwide equivalence or legal entitlement claim.","navigation":{"role":"solution","title":"Hamburg care counselling","summary":"Care counselling in Hamburg. Does not guarantee agreement or an available place."}}'::jsonb,'candidate','{"basis":"single_source","rationale":"Official Hamburg government service description with responsible bodies, audience and counseling routes. Publication/update date, access, capacity and outcomes unverified."}'::jsonb,'{"job_id":"5a45c0f8032af6072cd050ac64733d575b96d4694f4f912138b75c8f1936dab9","batch_id":"hamburg-counseling-internal-20261009-v1","finding_id":"finding-4dc82a66c6de4d2dbc432091","managed_by":"whocares-indexer.atlas-publish.v1","record_sha256":"714b22605389827736cc0f2965cb1bba620b1bc567faf797d42b45095ec54dd0","manifest_sha256":"13d4b68e4c38d57befd48ccaeb27b732d072c8188659f0a898c170e7a09652fc","editorial_review":{"actor":"Codex editorial supervision","reason":"Inspected complete official Hamburg capture and raw HTML date metadata; independently reviewed corrected scoped record. One Hamburg institutional counseling response with explicit responsible bodies, audience and counseling routes. Date open question stays supporting context; no date established. No access, capacity, national-coverage or outcome claim. Internal database duplicate identity checks returned no matching entries or objects. Preserve prior FLEXXI/legal holds. Reuse existing caregiver relief space with separately sourced editorial context relationship. Internal branch only.","reviewed_at":"2026-10-09T05:21:39.955007+00:00","audit_event_id":2350},"principles_sha256":"1698c1ce402af9694166b15938d24fb9fb05c55e85a330b4e589b7dca5b2a8c2","finding_review_hash":"900edc30eaa7bce9ed603471424092249b7c4ba9636e741387a44835cfeb6483","finding_payload_sha256":"e781229afd995f04c8d74623cae1bd8a6a4ecc7ffe17391933c8d2f24bde1cb9","original_epistemic_status":"candidate"}'::jsonb) ON CONFLICT (id) DO UPDATE SET scope=atlas.objects.scope || jsonb_build_object('navigation',EXCLUDED.scope->'navigation') WHERE atlas.objects.scope->'navigation' IS DISTINCT FROM EXCLUDED.scope->'navigation';
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('wc-object-1f8621db6526f94ba2ba4c89',NULL,'institutional_response','NachbarschaftsHilfe Pforzheim e.V. offers household help, accompaniment and conversation to older people in Pforzheim','NachbarschaftsHilfe Pforzheim e.V., a nonprofit association founded in 1974, describes supporting older and ill people in Pforzheim with household tasks, accompaniment to authorities and doctors, and simple conversation, individually adapted, with the stated aim of easing loneliness and enabling people to stay in their own homes; it says it is active in all 15 Pforzheim city districts.','{"time":"undated webpage; association founded 1974","method":"official provider website","people":"older and ill people in Pforzheim","geography":"Pforzheim, Germany (all 15 city districts per provider)","limitations":"Provider self-description on undated webpage; actual current capacity, demand, waiting times and outcomes unknown; no effectiveness claim","navigation":{"role":"solution","title":"NachbarschaftsHilfe Pforzheim","summary":"Household help and accompaniment in Pforzheim. Current capacity requires checking."}}'::jsonb,'candidate','{"basis":"single_source","rationale":"Official provider description supports stated activities and audience only; capacity, access and outcomes remain unknown."}'::jsonb,'{"job_id":"f0b180ed9e66f8e7ca539c9f52bc5057b0d5fe033e7486f6794b65c2195a63c4","batch_id":"services-internal-20261009-v1","finding_id":"finding-1d64b36131b439478d4176e2","managed_by":"whocares-indexer.atlas-publish.v1","record_sha256":"015e48a93f4001ba4ecfc98ca705a5ab3c9d123ef5c6d309fd935910d4a7d358","manifest_sha256":"fd2b3c8b331d30cdf057d362a1bc6224593469aa5f7d2c54ad29dfa722273898","editorial_review":{"actor":"Codex editorial supervision","reason":"Exact provider passages checked; DRK volunteering lookup removed from recipient-access claim. Two official sources, no matching existing names/offerings in queried preview baseline. Add scoped candidates to the existing problem space without changing taxonomy or asserting effectiveness. Internal preview branch only.","reviewed_at":"2026-10-08T23:00:58.920959+00:00","audit_event_id":825},"principles_sha256":"1698c1ce402af9694166b15938d24fb9fb05c55e85a330b4e589b7dca5b2a8c2","finding_review_hash":"4273423aca64d109580a9249a2f8e79453c0c005c1bdf21900c8d847cfec1463","finding_payload_sha256":"2b0e64a0394408300478de63d93d50cdede07346c6fe0c725303c0056038e89e","original_epistemic_status":"candidate"}'::jsonb) ON CONFLICT (id) DO UPDATE SET scope=atlas.objects.scope || jsonb_build_object('navigation',EXCLUDED.scope->'navigation') WHERE atlas.objects.scope->'navigation' IS DISTINCT FROM EXCLUDED.scope->'navigation';
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('wc-object-add32eb018abad005b10780a',NULL,'institutional_response','DRK Besuchsdienst: volunteer visits to older, often single-living people','The DRK describes a volunteer visiting service for older, often single-living people at home or in senior facilities, offering company, conversation, help with official forms, games, accompaniment and shopping help. The provider says usually no costs arise. Recipient intake, eligibility and availability in a particular locality are not established by the captured passages.','{"time":"undated webpage","method":"official provider website","people":"older, often single-living people","geography":"Germany, via local DRK Kreisverbände","limitations":"Undated provider description; recipient intake, eligibility, actual local capacity and visit frequency unknown; no independent effectiveness claim.","navigation":{"role":"solution","title":"DRK visiting service","summary":"Volunteer visiting service. Local arrangements and matching require checking."}}'::jsonb,'candidate','{"basis":"single_source","rationale":"Official provider description supports stated activities and audience only; capacity, access and outcomes remain unknown."}'::jsonb,'{"job_id":"f0b180ed9e66f8e7ca539c9f52bc5057b0d5fe033e7486f6794b65c2195a63c4","batch_id":"services-internal-20261009-v1","finding_id":"finding-ee95a91c30824e1698c6c11b","managed_by":"whocares-indexer.atlas-publish.v1","record_sha256":"f7bdf68df8e603b1adffaeae9e5c573a983b12ad0379cbf72dc119bbe6550dea","manifest_sha256":"fd2b3c8b331d30cdf057d362a1bc6224593469aa5f7d2c54ad29dfa722273898","editorial_review":{"actor":"Codex editorial supervision","reason":"Exact provider passages checked; DRK volunteering lookup removed from recipient-access claim. Two official sources, no matching existing names/offerings in queried preview baseline. Add scoped candidates to the existing problem space without changing taxonomy or asserting effectiveness. Internal preview branch only.","reviewed_at":"2026-10-08T23:00:58.920959+00:00","audit_event_id":825},"principles_sha256":"1698c1ce402af9694166b15938d24fb9fb05c55e85a330b4e589b7dca5b2a8c2","finding_review_hash":"2af20cca1cf6d832a6a696e7dcc1d88b1bb2c4c0b678a4999aa844d4f774cae5","finding_payload_sha256":"853a2ccfd35172147e7a21430b0951371ff5d72b8a87dd1f923ba823fc8d6f43","original_epistemic_status":"candidate"}'::jsonb) ON CONFLICT (id) DO UPDATE SET scope=atlas.objects.scope || jsonb_build_object('navigation',EXCLUDED.scope->'navigation') WHERE atlas.objects.scope->'navigation' IS DISTINCT FROM EXCLUDED.scope->'navigation';
INSERT INTO atlas.objects (id,entry_id,kind,title,statement,scope,epistemic_status,confidence,provenance) VALUES ('wc-object-2d070343f2e5e41b3cf2092e',NULL,'institutional_response','Puderbach Bürgerfahrdienst: volunteer rides with telephone booking','The municipal Puderbach page describes a volunteer-run Bürgerfahrdienst offering free rides mainly to older residents and people needing help, including doctors, pharmacies, shopping and social visits. It lists telephone booking on 02684/858-106 at14:30–15:30: Monday for Tuesday/Wednesday trips and Wednesday for Thursday trips. Listed journeys run Tuesday–Thursday08:10–16:00 within VG Puderbach, plus Wednesday trips to Dierdorf excluding shopping. The page says advance reservations are unavailable and only requests received by the telephone service are considered.','{"time":"Undated page captured October2026; May/June2026 cancellation notices do not verify current operation.","geography":"Verbandsgemeinde Puderbach, Rheinland-Pfalz, Germany (plus Wednesday trips to Dierdorf)","limitations":"Municipal service description, not verified current capacity, successful bookings or actual care-access outcomes. Stated audience is mainly older/help-needing residents, not formal eligibility criteria; listed booking rules and geographic restriction retained.","methodology":"Official municipal website description; no survey or usage data","navigation":{"role":"solution","title":"Puderbach community transport","summary":"Volunteer rides in Puderbach. Booking, accessibility and trip eligibility require checking."}}'::jsonb,'candidate','{"basis":"single_source","rationale":"Official municipal service description with booking conditions and area limits; current capacity, uptake and outcomes unverified."}'::jsonb,'{"job_id":"30cda92aeed4c2383f8e07657a604014c692f32f45d7cd3d61fa7371fe71f09a","batch_id":"puderbach-transport-internal-20261009-v1","finding_id":"finding-d9f1da60e735d1a4ab70f584","managed_by":"whocares-indexer.atlas-publish.v1","record_sha256":"e16f0fefffb24899cd5f7a9e1e718d576e33f7e0c2cb1163d3fee4b2efeaf6f0","manifest_sha256":"516c96d56c88076b1e428c92bb043d5678f0428c2b71bfacb007d618726fb953","editorial_review":{"actor":"Codex editorial supervision","reason":"Inspected complete saved municipal page and current independent review. One named local volunteer transport response; explicit booking days, telephone, operating area and Dierdorf no-shopping condition retained. No inferred actual October operation from May/June notices, current capacity, formal eligibility or outcomes. Database duplicate search found no Puderbach object/entry. Reuse participation space with separate context evidence. Internal branch only.","reviewed_at":"2026-10-09T02:20:54.463694+00:00","audit_event_id":1704},"principles_sha256":"1698c1ce402af9694166b15938d24fb9fb05c55e85a330b4e589b7dca5b2a8c2","finding_review_hash":"75f540e679db3f24015eb42ba62e0a631d7e8f445e5b5e3a16b44a45582bf1ea","finding_payload_sha256":"9450d3e71cec0aa8ae7e99d3b8f93d7dcee6b8953816c5b393c95ca8a4131bf5","original_epistemic_status":"candidate"}'::jsonb) ON CONFLICT (id) DO UPDATE SET scope=atlas.objects.scope || jsonb_build_object('navigation',EXCLUDED.scope->'navigation') WHERE atlas.objects.scope->'navigation' IS DISTINCT FROM EXCLUDED.scope->'navigation';
